4: import 'package:mockito/mockito.dart';
5: 
6: import '../mocks/repository.mocks.dart';
7: 
8: import 'widget.dart';
9: 
10: void main() {
11:   group('HomePage', () {
12:     final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
13:     final MockNewsRepository mockNewsRepository = MockNewsRepository();
14:     final MockSettingsRepository mockSettingsRepository = MockSettingsRepository();
15: 
16:     final ImageProvider homeImage = Image.asset('assets/icons/home.png').image;
17:     final ImageProvider newsImage = Image.asset('assets/icons/news.png').image;
18:     final IconData profileIcon = Icons.person;
19: 
20:     late Widget homeWidget;
21: 
22:     setUp(() {
23:       homeWidget = buildWidget(
24:         providers: [
25:           Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
26:           Provider<NewsRepository>.value(value: mockNewsRepository),
27:           Provider<SettingsRepository>.value(value: mockSettingsRepository),
28:         ],
29:         child: const HomePage(),
30:       );
31: 
32:       when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => const CurrencyPage(items: [], page: 0, hasMore: false));
33:       when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => []);
34:       when(mockSettingsRepository.readThemeMode()).thenReturn(AppThemeMode.system);
35:     });
36: 
37:     testWidgets('should display all navigation tabs with correct labels and icons', (WidgetTester tester) async {
38:       await tester.pumpWidget(homeWidget);
39:       await tester.pumpAndSettle();
40: 
41:       expect(find.widgetWithText(BottomNavigationBar, 'Новости'), findsOneWidget);
42:       expect(find.widgetWithText(BottomNavigationBar, 'Курс Валют'), findsOneWidget);
43:       expect(find.widgetWithText(BottomNavigationBar, 'Профиль'), findsOneWidget);
44: 
45:       expect(find.widgetWithImage(BottomNavigationBar, homeImage), findsOneWidget);
46:       expect(find.widgetWithImage(BottomNavigationBar, newsImage), findsOneWidget);
47:       expect(find.widgetWithIcon(BottomNavigationBar, profileIcon), findsOneWidget);
48:     });
49: 
50:     testWidgets('should navigate to correct pages when tabs are tapped', (WidgetTester tester) async {
51:       await tester.pumpWidget(homeWidget);
52:       await tester.pumpAndSettle();
53: 
54:       await tester.tap(find.image(homeImage));
55:       await tester.pump(const Duration(milliseconds: 300));
56:       expect(find.byType(CurrencyListPage), findsOneWidget);
57: 
58:       await tester.tap(find.image(newsImage));
59:       await tester.pump(const Duration(milliseconds: 300));
60:       expect(find.byType(NewsListPage), findsOneWidget);
61: 
62:       await tester.tap(find.byIcon(profileIcon));
63:       await tester.pump(const Duration(milliseconds: 300));
64:       expect(find.byType(ProfilePage), findsOneWidget);
65:     });
66:   });
67: }

